use super::*;
fn fixture()->(PathBuf,Value){let root=std::env::temp_dir().join(format!("starlane-archive-recovery-{}",random_operation().unwrap()));std::fs::create_dir(&root).unwrap();std::fs::create_dir(root.join("vault")).unwrap();let binding=json!({"context":{"session":"original"},"revision":"original-revision","root":root.join("vault")});(root,binding)}
fn unknown(root:&Path,b:&Value,leaf:&str)->String{let selected=Selected::admit(root.join(leaf),b.clone()).unwrap();let mut stage=Staged::create(selected,sha(b"manifest")).unwrap();stage.file.write_all(b"original ZIP bytes").unwrap();stage.seal().unwrap();let op=stage.journal.operation.clone();assert!(stage.publish(||Ok(()),||Ok(b.clone()),|p|if p=="journal"{Err("lost before link".into())}else{Ok(())}).is_err());op}
fn report(root:&Path,b:&Value,op:&str)->Value{pending(root,b).unwrap()["operations"].as_array().unwrap().iter().find(|r|r["operation"]==op).unwrap().clone()}
#[test]fn unknown_blocks_same_destination_until_named_review(){let(root,b)=fixture();let op=unknown(&root,&b,"out.zip");assert!(Selected::admit(root.join("out.zip"),b.clone()).unwrap_err_text().contains("review"));let r=report(&root,&b,&op);assert_eq!(r["state"],"unresolved_output_absent");let ack=acknowledge_review(&root,&op,&b,&r).unwrap();assert_eq!(ack["retry_authority"],false);assert_eq!(ack["cleanup_authority"],false);assert!(Selected::admit(root.join("out.zip"),b.clone()).is_ok());assert!(!root.join("out.zip").exists());assert!(root.join(format!(".starlane-archive-{op}/archive.zip")).exists());assert_eq!(acknowledge_review(&root,&op,&b,&r).unwrap()["replayed"],true);std::fs::remove_dir_all(root).unwrap();}
trait ErrorText{fn unwrap_err_text(self)->String;}impl ErrorText for Result<Selected,String>{fn unwrap_err_text(self)->String{match self{Err(e)=>e,Ok(_)=>panic!("expected refusal")}}}
#[test]fn old_new_operations_remain_independent(){let(root,b)=fixture();let old=unknown(&root,&b,"old.zip");let new=unknown(&root,&b,"new.zip");let r=report(&root,&b,&old);acknowledge_review(&root,&old,&b,&r).unwrap();assert_eq!(report(&root,&b,&old)["reviewed"],true);assert_eq!(report(&root,&b,&new)["reviewed"],false);assert!(Selected::admit(root.join("old.zip"),b.clone()).is_ok());assert!(Selected::admit(root.join("new.zip"),b.clone()).is_err());std::fs::remove_dir_all(root).unwrap();}
#[test]fn stale_context_report_journal_and_physical_drift_refuse(){for mode in["context","report","journal","physical"]{let(root,b)=fixture();let op=unknown(&root,&b,"out.zip");let r=report(&root,&b,&op);let mut expected=b.clone();let mut submitted=r.clone();if mode=="context"{expected["context"]["session"]=json!("foreign");}if mode=="report"{submitted["state"]=json!("published_verified");}if mode=="journal"{let p=root.join(format!(".starlane-archive-{op}/journal.json"));let mut bytes=std::fs::read(&p).unwrap();bytes.push(b' ');std::fs::write(p,bytes).unwrap();}if mode=="physical"{std::fs::write(root.join("out.zip"),b"original ZIP bytes").unwrap();}assert!(acknowledge_review(&root,&op,&expected,&submitted).is_err());assert!(!root.join(format!(".starlane-archive-{op}/review.json")).exists());std::fs::remove_dir_all(root).unwrap();}}
#[test]fn malformed_conflicting_and_bounded_registry_refuse(){let(root,b)=fixture();let op=unknown(&root,&b,"out.zip");let r=report(&root,&b,&op);acknowledge_review(&root,&op,&b,&r).unwrap();let p=root.join(format!(".starlane-archive-{op}/review.json"));std::fs::write(p,b"{}").unwrap();assert!(pending(&root,&b).is_err());assert!(Selected::admit(root.join("out.zip"),b.clone()).is_err());std::fs::remove_dir_all(root).unwrap();let(root,b)=fixture();for _ in 0..129{std::fs::create_dir(root.join(format!(".starlane-archive-{}",random_operation().unwrap()))).unwrap();}assert!(pending(&root,&b).unwrap_err().contains("128"));std::fs::remove_dir_all(root).unwrap();}
#[test]#[ignore="fresh process restart evidence worker; invoked by parent test"]fn fresh_process_review_worker(){let work=PathBuf::from(std::env::var("STARLANE_ARCHIVE_REVIEW_FIXTURE").expect("owned fixture required"));let input:Value=serde_json::from_slice(&std::fs::read(work.join("restart-input.json")).unwrap()).unwrap();let b=&input["binding"];let op=input["operation"].as_str().unwrap();assert!(Selected::admit(work.join("out.zip"),b.clone()).is_err());let rows=pending(&work,b).unwrap();let r=rows["operations"].as_array().unwrap().iter().find(|r|r["operation"]==op).unwrap();assert_eq!(r,&input["report"]);acknowledge_review(&work,op,b,r).unwrap();assert!(Selected::admit(work.join("out.zip"),b.clone()).is_ok());assert!(!work.join("out.zip").exists());println!("ACTUAL_FRESH_PROCESS_NAMED_REVIEW_NO_RETRY_NO_UNLINK_PASS");}
#[test]fn actual_fresh_process_restart_inspect_and_explicit_review(){let(root,b)=fixture();let op=unknown(&root,&b,"out.zip");let r=report(&root,&b,&op);std::fs::write(root.join("restart-input.json"),serde_json::to_vec(&json!({"binding":b,"operation":op,"report":r})).unwrap()).unwrap();let child=std::process::Command::new(std::env::current_exe().unwrap()).args(["local_database::attachment_download_owner::native_archive_output::recovery::tests::fresh_process_review_worker","--exact","--ignored","--nocapture"]).env("STARLANE_ARCHIVE_REVIEW_FIXTURE",&root).output().unwrap();assert!(child.status.success(),"{}",String::from_utf8_lossy(&child.stdout));assert!(String::from_utf8_lossy(&child.stdout).contains("ACTUAL_FRESH_PROCESS_NAMED_REVIEW_NO_RETRY_NO_UNLINK_PASS"));assert_eq!(report(&root,&b,&op)["reviewed"],true);assert!(!root.join("out.zip").exists());assert!(root.join(format!(".starlane-archive-{op}/archive.zip")).exists());std::fs::remove_dir_all(root).unwrap();}

#[test]fn equal_content_foreign_journal_after_report_or_review_refuses(){for prior_ack in [false,true]{let(root,b)=fixture();let op=unknown(&root,&b,"out.zip");let r=report(&root,&b,&op);if prior_ack{acknowledge_review(&root,&op,&b,&r).unwrap();}let p=root.join(format!(".starlane-archive-{op}/journal.json"));let bytes=std::fs::read(&p).unwrap();std::fs::rename(&p,p.with_extension("held")).unwrap();use std::os::unix::fs::OpenOptionsExt;let mut f=std::fs::OpenOptions::new().write(true).create_new(true).mode(0o600).open(&p).unwrap();f.write_all(&bytes).unwrap();f.sync_all().unwrap();assert!(acknowledge_review(&root,&op,&b,&r).is_err());if prior_ack{assert!(pending(&root,&b).is_err());}assert!(Selected::admit(root.join("out.zip"),b.clone()).is_err());std::fs::remove_dir_all(root).unwrap();}}

#[test]fn incomplete_same_inode_same_length_bytes_change_refuses_old_review(){let(root,b)=fixture();let selected=Selected::admit(root.join("out.zip"),b.clone()).unwrap();let mut stage=Staged::create(selected,sha(b"manifest")).unwrap();stage.file.write_all(b"original").unwrap();stage.file.sync_all().unwrap();let op=stage.journal.operation.clone();let r=report(&root,&b,&op);use std::os::unix::fs::FileExt;stage.file.write_at(b"replaced",0).unwrap();stage.file.sync_all().unwrap();assert!(acknowledge_review(&root,&op,&b,&r).is_err());assert!(!stage.dir.path.join("review.json").exists());std::fs::remove_dir_all(root).unwrap();}
